type Input=Record<string,unknown>;
type Ctx={session:AdministrativeSession;permissions:Set<PermissionCode>};
type Unit={id:number;name:string;type:"CONVENCAO"|"MATRIZ"|"FILIAL";parent_id:number|null;matrixId:number;branchId:number|null};
type Period={id:number;tenant_id:number;unit_id:number;unit_type:"MATRIZ"|"FILIAL";matrix_id:number;branch_id:number|null;competency:string;status:"ABERTO"|"FECHADO";lifecycle_state:"ABERTO"|"REABERTO"|"FECHADO";version:number;reopen_count:number;closure_version:number;opened_at:string;opened_by_user_id:number;closed_at:string|null;reopened_at:string|null};
const now=()=>new Date().toISOString();
const clean=(value:unknown,max=500)=>typeof value==="string"?value.trim().replace(/[<>]/g,"").slice(0,max):"";
const positive=(value:unknown)=>{const n=Number(value);if(!Number.isInteger(n)||n<=0)throw new ApiError(400,"DADOS_INVALIDOS","Registro inválido.");return n;};
const positiveOptional=(value:unknown)=>{if(value===null||value===undefined||value==="")return null;return positive(value);};
const competency=(value:unknown)=>{const result=clean(value,7);if(!/^\d{4}-(0[1-9]|1[0-2])$/.test(result))throw new ApiError(400,"COMPETENCIA_INVALIDA","Informe uma competência válida.");return result;};
const isoDate=(value:unknown)=>{const result=clean(value,10);if(!/^\d{4}-\d{2}-\d{2}$/.test(result))throw new ApiError(400,"DATA_INVALIDA","Informe uma data válida.");return result;};
const periodTotalsSql=`SELECT
  COALESCE(SUM(CASE WHEN m.status IN ('CONFIRMADO','ESTORNADO') AND (m.direction='ENTRADA' OR (m.direction='AJUSTE' AND m.adjustment_direction='ENTRADA') OR (m.direction='ESTORNO' AND m.reversal_direction='ENTRADA')) THEN m.amount_cents ELSE 0 END),0) total_entries_cents,
  COALESCE(SUM(CASE WHEN m.status IN ('CONFIRMADO','ESTORNADO') AND (m.direction='SAIDA' OR (m.direction='AJUSTE' AND m.adjustment_direction='SAIDA') OR (m.direction='ESTORNO' AND m.reversal_direction='SAIDA')) THEN m.amount_cents ELSE 0 END),0) total_expenses_cents,
  COALESCE(SUM(CASE WHEN m.fund_id IS NOT NULL AND m.status IN ('CONFIRMADO','ESTORNADO') AND (m.direction='ENTRADA' OR (m.direction='ESTORNO' AND m.reversal_direction='ENTRADA')) THEN m.amount_cents WHEN m.fund_id IS NOT NULL AND m.status IN ('CONFIRMADO','ESTORNADO') AND (m.direction='SAIDA' OR (m.direction='ESTORNO' AND m.reversal_direction='SAIDA')) THEN -m.amount_cents ELSE 0 END),0) restricted_resources_cents,
  COALESCE(SUM(CASE WHEN m.status IN ('CONFIRMADO','ESTORNADO') AND m.direction='ENTRADA' AND m.category_id IN (SELECT value FROM json_each((SELECT participating_category_ids_json FROM finance_period_allocation_rules pr WHERE pr.tenant_id=m.tenant_id AND pr.period_id=m.period_id ORDER BY pr.display_order LIMIT 1))) AND m.campaign_id IS NULL AND (m.fund_id IS NULL OR COALESCE(f.restricted,0)=0) THEN m.amount_cents WHEN m.status='CONFIRMADO' AND m.direction='ESTORNO' AND m.reversal_direction='SAIDA' AND m.category_id IN (SELECT value FROM json_each((SELECT participating_category_ids_json FROM finance_period_allocation_rules pr WHERE pr.tenant_id=m.tenant_id AND pr.period_id=m.period_id ORDER BY pr.display_order LIMIT 1))) AND m.campaign_id IS NULL AND (m.fund_id IS NULL OR COALESCE(f.restricted,0)=0) THEN -m.amount_cents ELSE 0 END),0) eligible_base_cents,
  COUNT(CASE WHEN m.status IN ('CONFIRMADO','ESTORNADO') THEN 1 END) movement_count
  FROM finance_movements m LEFT JOIN finance_categories c ON c.id=m.category_id AND c.tenant_id=m.tenant_id LEFT JOIN finance_funds f ON f.id=m.fund_id AND f.tenant_id=m.tenant_id WHERE m.tenant_id=? AND m.period_id=?`;
async function context(request:Request,permission:PermissionCode):Promise<Ctx>{const {session,permissions}=await requirePermission(request,permission);return{session,permissions};}
async function contextAny(request:Request,permissions:readonly PermissionCode[]):Promise<Ctx>{const result=await requireAnyPermission(request,permissions);return{session:result.session,permissions:result.permissions};}

async function unit(ctx:Ctx,unitId:number):Promise<Unit>{const row=await database().prepare("SELECT id,name,type,parent_id,status,archived_at FROM organizational_units WHERE id=? AND tenant_id=?").bind(unitId,ctx.session.user.tenantId).first<{id:number;name:string;type:string;parent_id:number|null;status:string;archived_at:string|null}>();if(!row||row.status!=="ATIVO"||row.archived_at||!(["CONVENCAO","MATRIZ","FILIAL"] as string[]).includes(row.type))throw new ApiError(404,"UNIDADE_NAO_ENCONTRADA","Unidade financeira não encontrada.");if(ctx.session.activeContext?.unitId!==row.id)throw new ApiError(403,"FORA_DO_ESCOPO","Selecione esta unidade no topo antes de operar o caixa.");const matrixId=row.type==="FILIAL"?row.parent_id:row.id,branchId=row.type==="FILIAL"?row.id:null;if(!matrixId||(row.type!=="CONVENCAO"&&!canAccessMemberScope(ctx.session.user,{tenantId:ctx.session.user.tenantId,matrixId,branchId}))||row.type==="CONVENCAO"&&ctx.session.user.scope!=="CONVENCAO")throw new ApiError(403,"FORA_DO_ESCOPO","Unidade fora do seu escopo.");return{...row,type:row.type as Unit["type"],matrixId,branchId};}
function audit(ctx:Ctx,action:string,entityType:string,entityId:number,unitId:number,before:unknown,next:unknown,reason:string|null=null){return database().prepare("INSERT INTO finance_audit(tenant_id,unit_id,actor_user_id,actor_membership_id,action,entity_type,entity_id,previous_values,new_values,reason,created_at) VALUES(?,?,?,?,?,?,?,?,?,?,?)").bind(ctx.session.user.tenantId,unitId,ctx.session.user.id,ctx.session.user.membershipId,action,entityType,entityId,before?JSON.stringify(before):null,next?JSON.stringify(next):null,reason,now());}
function normalizeAllocationRules(raw:unknown):Array<AllocationRule&{recipientName:string;recipientType:string;ruleType:string;percentageBasisPoints:number|null;fixedAmountCents:number|null;financialDestination:"REPASSAR"|"MANTER_NA_UNIDADE";destinationUnitId:number|null;destinationDepartmentId:number|null;displayOrder:number;description:string|null;active:boolean}>{
  if(!Array.isArray(raw)||!raw.length)throw new ApiError(400,"RATEIO_VAZIO","Adicione pelo menos uma divisão.");
  const rules=raw.map((value,index)=>{const row=value&&typeof value==="object"?value as Input:{},recipientName=clean(row.recipientName,120),recipientType=clean(row.recipientType,30)||"OUTRO",ruleType=clean(row.ruleType,20)||"PERCENTUAL",financialDestination=clean(row.financialDestination,30),destinationUnitId=positiveOptional(row.destinationUnitId),destinationDepartmentId=positiveOptional(row.destinationDepartmentId),percentageBasisPoints=ruleType==="PERCENTUAL"?Math.round(Number(row.percentage)*100):null,fixedAmountCents=ruleType==="FIXO"?Math.round(Number(row.fixedAmountCents)):null;if(!recipientName||!(["PASTOR","VICE_PASTOR","DIRIGENTE","MATRIZ","CONVENCAO","IGREJA","CONGREGACAO","ASSISTENCIA","MISSOES","FUNDO","OUTRO"] as string[]).includes(recipientType))throw new ApiError(400,"RATEIO_INVALIDO",`Revise o destinatário da divisão ${index+1}.`);if(!(["REPASSAR","MANTER_NA_UNIDADE"] as string[]).includes(financialDestination))throw new ApiError(400,"DESTINACAO_FINANCEIRA_OBRIGATORIA",`Selecione Repassar ou Permanecer na unidade na divisão ${index+1}.`);if(financialDestination==="REPASSAR"&&!destinationUnitId)throw new ApiError(400,"UNIDADE_DESTINO_OBRIGATORIA",`Selecione a unidade que receberá a divisão ${index+1}.`);return{recipientName,recipientType,ruleType,percentageBasisPoints,fixedAmountCents,financialDestination:financialDestination as "REPASSAR"|"MANTER_NA_UNIDADE",destinationUnitId:financialDestination==="REPASSAR"?destinationUnitId:null,destinationDepartmentId:financialDestination==="REPASSAR"?destinationDepartmentId:null,displayOrder:index+1,description:clean(row.description,300)||null,active:row.active!==false};});
  const validation=validateAllocationRules(rules);if(!validation.valid){const message=validation.code==="SALDO_RESTANTE_DUPLICADO"?"Permita somente um destinatário como Saldo Restante.":validation.code==="VALOR_FIXO_INVALIDO"?"Informe um valor fixo positivo em centavos.":validation.code==="PERCENTUAL_EXCEDENTE"?"A soma dos percentuais não pode ultrapassar 100%.":"Revise os tipos e valores das divisões.";throw new ApiError(400,validation.code||"RATEIO_INVALIDO",message);}return rules;
}
async function validateAllocationDestinations(ctx:Ctx,source:Unit,rules:ReturnType<typeof normalizeAllocationRules>){for(const rule of rules){if(rule.financialDestination!=="REPASSAR"||!rule.destinationUnitId)continue;const destination=await database().prepare("SELECT id,type,parent_id,status,archived_at FROM organizational_units WHERE id=? AND tenant_id=?").bind(rule.destinationUnitId,ctx.session.user.tenantId).first<{id:number;type:string;parent_id:number|null;status:string;archived_at:string|null}>();if(!destination||destination.status!=="ATIVO"||destination.archived_at||!(["CONVENCAO","MATRIZ","FILIAL"] as string[]).includes(destination.type))throw new ApiError(400,"UNIDADE_DESTINO_INVALIDA",`A unidade de destino da divisão ${rule.displayOrder} não está disponível.`);if(ctx.session.user.scope!=="CONVENCAO"){const allowed=destination.id===source.id||destination.id===source.matrixId||destination.parent_id===source.matrixId||destination.type==="CONVENCAO";if(!allowed)throw new ApiError(403,"DESTINO_FORA_DA_REDE",`A unidade de destino da divisão ${rule.displayOrder} não pertence à rede da Matriz.`);}if(rule.destinationDepartmentId){const department=await database().prepare("SELECT id FROM departments WHERE id=? AND tenant_id=? AND unit_id=? AND status='ATIVO'").bind(rule.destinationDepartmentId,ctx.session.user.tenantId,destination.id).first();if(!department)throw new ApiError(400,"DEPARTAMENTO_DESTINO_INVALIDO",`O departamento da divisão ${rule.displayOrder} não pertence à unidade escolhida.`);}}}
function allocationPreview(totals:Record<string,unknown>|null,rules:AllocationRule[]){const totalEntries=Number(totals?.total_entries_cents||0),base=Math.max(0,Number(totals?.eligible_base_cents||0)),excluded=Math.max(0,totalEntries-base),calculation=calculateAllocation(base,rules),ownUnitAllocationCents=calculation.results.filter(row=>row.financialDestination==="MANTER_NA_UNIDADE").reduce((sum,row)=>sum+row.calculatedAmountCents,0),calculatedToTransferCents=calculation.results.filter(row=>row.financialDestination==="REPASSAR").reduce((sum,row)=>sum+row.calculatedAmountCents,0);return{totalEntriesCents:totalEntries,excludedResourcesCents:excluded,eligibleBaseCents:base,ownUnitAllocationCents,calculatedToTransferCents,pendingTransferCents:calculatedToTransferCents,...calculation};}
async function periodById(ctx:Ctx,periodId:number){const row=await database().prepare("SELECT * FROM finance_periods WHERE id=? AND tenant_id=?").bind(periodId,ctx.session.user.tenantId).first<Period>();if(!row)throw new ApiError(404,"PERIODO_NAO_ENCONTRADO","Período financeiro não encontrado.");await unit(ctx,row.unit_id);return row;}

export async function assertOpenFinancePeriod(session:AdministrativeSession,unitId:number,periodCompetency:string){const row=await database().prepare("SELECT id,status,lifecycle_state,reopen_count,closure_version FROM finance_periods WHERE tenant_id=? AND unit_id=? AND competency=?").bind(session.user.tenantId,unitId,periodCompetency).first<{id:number;status:string;lifecycle_state:string;reopen_count:number;closure_version:number}>();if(!row)throw new ApiError(409,"CAIXA_NAO_ABERTO",`Abra o caixa de ${periodCompetency.slice(5,7)}/${periodCompetency.slice(0,4)} antes de realizar lançamentos.`);if(row.status!=="ABERTO")throw new ApiError(409,"CAIXA_FECHADO",`O período ${periodCompetency.slice(5,7)}/${periodCompetency.slice(0,4)} está fechado e não aceita novos lançamentos.`);return row;}

export async function assertOpenFinancePeriodById(session:AdministrativeSession,unitId:number,periodId=0){const row=periodId?await database().prepare("SELECT id,status,lifecycle_state,reopen_count,closure_version,competency FROM finance_periods WHERE tenant_id=? AND unit_id=? AND id=?").bind(session.user.tenantId,unitId,periodId).first<{id:number;status:string;lifecycle_state:string;reopen_count:number;closure_version:number;competency:string}>():await database().prepare("SELECT id,status,lifecycle_state,reopen_count,closure_version,competency FROM finance_periods WHERE tenant_id=? AND unit_id=? AND status='ABERTO' ORDER BY COALESCE(reopened_at,opened_at) DESC,competency DESC,id DESC LIMIT 1").bind(session.user.tenantId,unitId).first<{id:number;status:string;lifecycle_state:string;reopen_count:number;closure_version:number;competency:string}>();if(!row)throw new ApiError(409,"CAIXA_NAO_ABERTO","Abra um caixa financeiro para esta unidade antes de realizar lançamentos.");if(row.status!=="ABERTO")throw new ApiError(409,"CAIXA_FECHADO",`O caixa ${row.competency.slice(5,7)}/${row.competency.slice(0,4)} está fechado e não aceita novos lançamentos.`);return row;}

