    const entryCents=Number(closure.total_entries_cents||0),expenseCents=Number(closure.total_expenses_cents||0),eligibleCents=Number(closure.eligible_base_cents||0),excludedCents=Number(closure.excluded_resources_cents||Math.max(0,entryCents-eligibleCents)),allocatedCents=Number(closure.allocated_cents||results.reduce((sum,row)=>sum+row.calculatedAmountCents,0));
