async function sendPeriodNotification(ctx:Ctx,unitId:number,type:string,title:string,message:string,entityId:number){const recipients=await database().prepare("SELECT DISTINCT m.user_id FROM tenant_memberships m JOIN membership_permissions p ON p.membership_id=m.id WHERE m.tenant_id=? AND m.status='ATIVO' AND m.archived_at IS NULL AND p.permission='FINANCEIRO_VISUALIZAR' AND (m.scope='CONVENCAO' OR m.scope_unit_id=? OR EXISTS(SELECT 1 FROM organizational_units u WHERE u.id=? AND u.parent_id=m.scope_unit_id))").bind(ctx.session.user.tenantId,unitId,unitId).all<{user_id:number}>();if(!recipients.results.length)return;const notificationId=generatedId(),stamp=now(),repass=type==="FINANCEIRO_REPASSE_GERADO";await database().batch([database().prepare("INSERT INTO notifications(id,tenant_id,audience,type,title,message,priority,internal_route,source_entity,source_entity_id,unit_id,group_key,metadata_json,mandatory,created_at,updated_at) VALUES(?,?,'ORGANIZATIONAL',?,?,?,?,?,?,?,?,?,'{}',0,?,?)").bind(notificationId,ctx.session.user.tenantId,type,title,message,repass?"IMPORTANTE":"ATENCAO",repass?"/painel/financeiro?aba=repasses":"/painel/financeiro?aba=caixa",repass?"FINANCE_INTERUNIT_REPASS":"FINANCE_PERIOD",entityId,unitId,`${type}:${entityId}:${stamp}`,stamp,stamp),...recipients.results.map(row=>database().prepare("INSERT INTO notification_recipients(notification_id,user_id,created_at) VALUES(?,?,?)").bind(notificationId,row.user_id,stamp))]);}

