  const personId=input.personId?positive(input.personId):null,person=personId?await quickPerson(ctx,selectedUnit,personId):null,privacy=(clean(input.privacy,30)||(person?person.default_privacy:"ANONIMA")) as FinancePrivacy;
  try{contributionIdentity(privacy,personId);}catch{throw new ApiError(400,"CONTRIBUINTE_OBRIGATORIO","Selecione uma Pessoa ou use Anônima.");}
