  if(!Number.isSafeInteger(amount)||amount<=0)throw new ApiError(400,"VALOR_INVALIDO","Informe um valor positivo.");
  const type=clean(input.contributionType,30)||session.default_contribution_type;if(!(["DIZIMO","OFERTA","VOTO","DOACAO","MISSOES","CAMPANHA","OFERTA_VOLUNTARIA","OUTRA"] as string[]).includes(type))throw new ApiError(400,"TIPO_INVALIDO","Tipo de contribuição inválido.");
  const movementId=generatedId(),contributionId=generatedId(),stamp=now(),campaignId=type==="CAMPANHA"&&input.campaignId?positive(input.campaignId):null,paymentMethodId=input.paymentMethodId?positive(input.paymentMethodId):session.default_payment_method_id,categoryId=positive(input.categoryId);
  if(type==="CAMPANHA"&&!campaignId)throw new ApiError(400,"CAMPANHA_OBRIGATORIA","Selecione a campanha deste lançamento.");
  const campaign=await quickCampaign(ctx,session.unit_id,campaignId),fundId=campaign?.fund_id??null;
  await validateFinanceCategory({tenantId:ctx.session.user.tenantId,categoryId,expectedKind:"RECEITA",fundId,required:true});
  if(paymentMethodId&&!await database().prepare("SELECT id FROM finance_payment_methods WHERE id=? AND tenant_id=? AND status='ATIVO'").bind(paymentMethodId,ctx.session.user.tenantId).first())throw new ApiError(400,"FORMA_INVALIDA","Selecione uma forma de recebimento ativa.");
  const createdDuringReopening=currentPeriod.closure_version>0?1:0;
